"use client";

import { useId } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
	DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { CreditCardIcon, WalletIcon } from "lucide-react";
import { usePaymentInputs } from "react-payment-inputs";
import images, { type CardImages } from "react-payment-inputs/images";

export default function Component() {
	const id = useId();
	const {
		meta,
		getCardNumberProps,
		getExpiryDateProps,
		getCVCProps,
		getCardImageProps,
	} = usePaymentInputs();

	return (
		<Dialog>
			<DialogTrigger asChild>
				<Button variant="outline">Card details</Button>
			</DialogTrigger>
			<DialogContent>
				<div className="flex flex-col gap-2">
					<div
						className="flex size-11 shrink-0 items-center justify-center rounded-full border"
						aria-hidden="true"
					>
						<WalletIcon className="opacity-80" size={16} />
					</div>
					<DialogHeader>
						<DialogTitle className="text-left">
							Update your card
						</DialogTitle>
						<DialogDescription className="text-left">
							Your new card will replace your current card.
						</DialogDescription>
					</DialogHeader>
				</div>

				<form className="space-y-5">
					<div className="space-y-4">
						<div className="*:not-first:mt-2">
							<Label htmlFor={`name-${id}`}>Name on card</Label>
							<Input id={`name-${id}`} type="text" required />
						</div>
						<div className="*:not-first:mt-2">
							<Label htmlFor={`number-${id}`}>Card Number</Label>
							<div className="relative">
								<Input
									{...getCardNumberProps()}
									id={`number-${id}`}
									className="peer pe-9 [direction:inherit]"
								/>
								<div className="text-muted-foreground/80 pointer-events-none absolute inset-y-0 end-0 flex items-center justify-center pe-3 peer-disabled:opacity-50">
									{meta.cardType ? (
										<svg
											className="overflow-hidden rounded-sm"
											{...getCardImageProps({
												images: images as unknown as CardImages,
											})}
											width={20}
										/>
									) : (
										<CreditCardIcon size={16} aria-hidden="true" />
									)}
								</div>
							</div>
						</div>
						<div className="flex gap-4">
							<div className="flex-1 space-y-2">
								<Label htmlFor={`expiry-${id}`}>Expiry date</Label>
								<Input
									className="[direction:inherit]"
									{...getExpiryDateProps()}
									id={`expiry-${id}`}
								/>
							</div>
							<div className="flex-1 space-y-2">
								<Label htmlFor={`cvc-${id}`}>CVC</Label>
								<Input
									className="[direction:inherit]"
									{...getCVCProps()}
									id={`cvc-${id}`}
								/>
							</div>
						</div>
					</div>
					<div className="flex items-center gap-2">
						<Checkbox id={`primary-${id}`} />
						<Label
							htmlFor={`primary-${id}`}
							className="text-muted-foreground font-normal"
						>
							Set as default payment method
						</Label>
					</div>
					<Button type="button" className="w-full">
						Update card
					</Button>
				</form>
			</DialogContent>
		</Dialog>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import { Check } from "lucide-react";

const Checkbox = React.forwardRef<
	React.ElementRef<typeof CheckboxPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>
>(({ className, ...props }, ref) => (
	<CheckboxPrimitive.Root
		ref={ref}
		className={cn(
			"peer h-4 w-4 shrink-0 rounded-sm border border-primary ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground",
			className
		)}
		{...props}
	>
		<CheckboxPrimitive.Indicator
			className={cn("flex items-center justify-center text-current")}
		>
			<Check className="h-4 w-4" />
		</CheckboxPrimitive.Indicator>
	</CheckboxPrimitive.Root>
));
Checkbox.displayName = CheckboxPrimitive.Root.displayName;

export { Checkbox };

